// ---- sha256_functions.v ------------------------------------------------
// =============================================================================
// sha256_functions.v
// Pure combinational SHA-256 sub-functions (Fig. 7 building blocks)
//
// Implements:
//   Sigma0, Sigma1  : big-sigma compression functions (on a and e)
//   sigma0, sigma1  : small-sigma message schedule functions
//   Ch, Maj         : choice and majority functions
// All operate on 32-bit words with 32-bit XOR/AND/OR (bitwise).
// =============================================================================

// -----------------------------------------------------------------------------
// Big-Sigma-0: used on working variable 'a' (upper path, Fig. 7)
//   Sigma0(a) = ROTR2(a) XOR ROTR13(a) XOR ROTR22(a)
// -----------------------------------------------------------------------------
module sha256_Sigma0 (
    input  [31:0] x,
    output [31:0] y
);
    assign y = {x[1:0],  x[31:2]}  ^   // ROTR2
               {x[12:0], x[31:13]} ^   // ROTR13
               {x[21:0], x[31:22]};    // ROTR22
endmodule

// -----------------------------------------------------------------------------
// Big-Sigma-1: used on working variable 'e' (lower path, Fig. 7)
//   Sigma1(e) = ROTR6(e) XOR ROTR11(e) XOR ROTR25(e)
// -----------------------------------------------------------------------------
module sha256_Sigma1 (
    input  [31:0] x,
    output [31:0] y
);
    assign y = {x[5:0],  x[31:6]}  ^   // ROTR6
               {x[10:0], x[31:11]} ^   // ROTR11
               {x[24:0], x[31:25]};    // ROTR25
endmodule

// -----------------------------------------------------------------------------
// Small-sigma-0: used in message schedule
//   sigma0(x) = ROTR7(x) XOR ROTR18(x) XOR SHR3(x)
// -----------------------------------------------------------------------------
module sha256_sigma0 (
    input  [31:0] x,
    output [31:0] y
);
    assign y = {x[6:0],  x[31:7]}  ^   // ROTR7
               {x[17:0], x[31:18]} ^   // ROTR18
               {3'b000,  x[31:3]};     // SHR3 (logical, zero-fill)
endmodule

// -----------------------------------------------------------------------------
// Small-sigma-1: used in message schedule
//   sigma1(x) = ROTR17(x) XOR ROTR19(x) XOR SHR10(x)
// -----------------------------------------------------------------------------
module sha256_sigma1 (
    input  [31:0] x,
    output [31:0] y
);
    assign y = {x[16:0], x[31:17]} ^   // ROTR17
               {x[18:0], x[31:19]} ^   // ROTR19
               {10'b0,   x[31:10]};    // SHR10 (logical, zero-fill)
endmodule

// -----------------------------------------------------------------------------
// Ch (Choice): lower-path function on e, f, g (Fig. 7)
//   Ch(e,f,g) = (e AND f) XOR (NOT_e AND g)
// -----------------------------------------------------------------------------
module sha256_Ch (
    input  [31:0] e,
    input  [31:0] f,
    input  [31:0] g,
    output [31:0] y
);
    assign y = (e & f) ^ (~e & g);
endmodule

// -----------------------------------------------------------------------------
// Maj (Majority): upper-path function on a, b, c (Fig. 7)
//   Maj(a,b,c) = (a AND b) XOR (a AND c) XOR (b AND c)
// -----------------------------------------------------------------------------
module sha256_Maj (
    input  [31:0] a,
    input  [31:0] b,
    input  [31:0] c,
    output [31:0] y
);
    assign y = (a & b) ^ (a & c) ^ (b & c);
endmodule

// ---- sha256_round.v ----------------------------------------------------
// =============================================================================
// sha256_round.v
// One iteration of the SHA-256 round function — DIRECT hardware map of Fig. 7.
//
// DATAPATH (combinational, matches Fig. 7 left-to-right):
//
//   UPPER PATH  (computes new 'a'):
//     Sigma0(a)  --> |
//     Maj(a,b,c) --> [+] --> T2
//
//   LOWER PATH  (computes new 'e'):
//     Sigma1(e)    -->|
//     Ch(e,f,g)    -->|
//     h            -->|
//     Wt + Kt ----->[+]--> [+] --> T1
//
//   OUTPUT WIRES (a' through h', Fig. 7 right side):
//     a' = T1 + T2
//     b' = a
//     c' = b
//     d' = c
//     e' = d + T1
//     f' = e
//     g' = f
//     h' = g
//
// All adders are mod-2^32 (carry truncated), matching ⊞ in the diagram.
// =============================================================================

module sha256_round (
    // Current working variables (left side of Fig. 7)
    input  [31:0] a, b, c, d, e, f, g, h,
    // Round word and constant
    input  [31:0] Wt,
    input  [31:0] Kt,
    // Updated working variables (right side of Fig. 7, one iteration)
    output [31:0] a_new, b_new, c_new, d_new,
    output [31:0] e_new, f_new, g_new, h_new
);
    // -------------------------------------------------------------------------
    // Instantiate sub-functions (Fig. 7 blocks)
    // -------------------------------------------------------------------------
    wire [31:0] S0_out;   // Sigma0(a)
    wire [31:0] S1_out;   // Sigma1(e)
    wire [31:0] maj_out;  // Maj(a,b,c)
    wire [31:0] ch_out;   // Ch(e,f,g)

    sha256_Sigma0 u_S0  (.x(a),         .y(S0_out));
    sha256_Sigma1 u_S1  (.x(e),         .y(S1_out));
    sha256_Maj    u_Maj (.a(a), .b(b), .c(c), .y(maj_out));
    sha256_Ch     u_Ch  (.e(e), .f(f), .g(g), .y(ch_out));

    // -------------------------------------------------------------------------
    // T2 = Sigma0(a) + Maj(a,b,c)   [upper adder in Fig. 7]
    // -------------------------------------------------------------------------
    wire [31:0] T2;
    assign T2 = S0_out + maj_out;      // mod 2^32 implicit in Verilog

    // -------------------------------------------------------------------------
    // T1 = h + Sigma1(e) + Ch(e,f,g) + Wt + Kt
    // Fig. 7 shows the bottom adder first combines Wt+Kt,
    // then feeds into the chain with Ch, Sigma1, h.
    // -------------------------------------------------------------------------
    wire [31:0] WK;                    // Wt + Kt  (bottom adder box, Fig. 7)
    assign WK = Wt + Kt;

    wire [31:0] T1;
    assign T1 = h + S1_out + ch_out + WK;

    // -------------------------------------------------------------------------
    // Output: rotated working variables  a'–h'  (right side of Fig. 7)
    // -------------------------------------------------------------------------
    assign a_new = T1 + T2;            // new a = T1 + T2
    assign b_new = a;                  // new b = old a  (wire passthrough)
    assign c_new = b;
    assign d_new = c;
    assign e_new = d + T1;             // new e = d + T1
    assign f_new = e;
    assign g_new = f;
    assign h_new = g;

endmodule

// ---- sha256_schedule.v -------------------------------------------------
// =============================================================================
// sha256_schedule.v  —  Message Schedule
//
// 16-word circular shift register. Wt_o = buf[0] (current round's word).
// load_i  : combinational, driven high during ST_LOAD  by sha256_core
// advance_i: combinational, driven high during ST_ROUND by sha256_core
// =============================================================================

module sha256_schedule (
    input         clk,
    input         rst_n,
    input         load_i,
    input [511:0] block_i,
    input         advance_i,
    output [31:0] Wt_o
);
    reg [31:0] buf0,  buf1,  buf2,  buf3,
               buf4,  buf5,  buf6,  buf7,
               buf8,  buf9,  buf10, buf11,
               buf12, buf13, buf14, buf15;

    // sigma1(buf14) = ROTR17 ^ ROTR19 ^ SHR10
    wire [31:0] sig1;
    assign sig1 = {buf14[16:0], buf14[31:17]} ^
                  {buf14[18:0], buf14[31:19]} ^
                  {10'b0, buf14[31:10]};

    // sigma0(buf1) = ROTR7 ^ ROTR18 ^ SHR3
    wire [31:0] sig0;
    assign sig0 = {buf1[6:0],  buf1[31:7]}  ^
                  {buf1[17:0], buf1[31:18]} ^
                  {3'b0, buf1[31:3]};

    // W[t] = sigma1(W[t-2]) + W[t-7] + sigma0(W[t-15]) + W[t-16]
    wire [31:0] W_new;
    assign W_new = sig1 + buf9 + sig0 + buf0;

    assign Wt_o = buf0;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            buf0<=0; buf1<=0; buf2<=0;  buf3<=0;
            buf4<=0; buf5<=0; buf6<=0;  buf7<=0;
            buf8<=0; buf9<=0; buf10<=0; buf11<=0;
            buf12<=0; buf13<=0; buf14<=0; buf15<=0;
        end
        else if (load_i) begin
            // Load 16 big-endian 32-bit words: word 0 = block_i[511:480]
            buf0  <= block_i[511:480]; buf1  <= block_i[479:448];
            buf2  <= block_i[447:416]; buf3  <= block_i[415:384];
            buf4  <= block_i[383:352]; buf5  <= block_i[351:320];
            buf6  <= block_i[319:288]; buf7  <= block_i[287:256];
            buf8  <= block_i[255:224]; buf9  <= block_i[223:192];
            buf10 <= block_i[191:160]; buf11 <= block_i[159:128];
            buf12 <= block_i[127:96];  buf13 <= block_i[95:64];
            buf14 <= block_i[63:32];   buf15 <= block_i[31:0];
        end
        else if (advance_i) begin
            // Shift: buf0 consumed, W_new appended at buf15
            buf0<=buf1; buf1<=buf2; buf2<=buf3;   buf3<=buf4;
            buf4<=buf5; buf5<=buf6; buf6<=buf7;   buf7<=buf8;
            buf8<=buf9; buf9<=buf10; buf10<=buf11; buf11<=buf12;
            buf12<=buf13; buf13<=buf14; buf14<=buf15; buf15<=W_new;
        end
    end

endmodule

// ---- sha256_core.v -----------------------------------------------------
// =============================================================================
// sha256_core.v  —  SHA-256 Compression Core
//
// Implements the full SHA-256 block compression as described in NIST FIPS 180-4,
// directly mirroring the hardware architecture of Fig. 7.
//
// STATE MACHINE (68 cycles per 512-bit block):
//   IDLE  (1 cy) : wait for block_valid_i
//   LOAD  (1 cy) : latch a-h = H0-H7, drive sched_load (combinational)
//   ROUND (64 cy): 64-round compression loop, drive sched_advance (combinational)
//   ACCUM (1 cy) : H' = H + [a..h]  (right-side adders in Fig. 7)
//   DONE  (1 cy) : pulse done_o, return to IDLE
//
// KEY TIMING DESIGN:
//   sched_load    is a COMBINATIONAL wire = (state == ST_LOAD)
//   sched_advance is a COMBINATIONAL wire = (state == ST_ROUND)
//   This guarantees sha256_schedule latches W[0..15] at the posedge that
//   transitions LOAD->ROUND, so Wt_o = W[0] is valid at the very first
//   ST_ROUND cycle with round_cnt = 0.  Each subsequent posedge in ST_ROUND
//   shifts the schedule and presents W[round_cnt] correctly.
// =============================================================================

module sha256_core (
    input         clk,
    input         rst_n,
    input         init_i,          // re-init hash state to IV (between messages)
    input         block_valid_i,   // pulse: new 512-bit block available
    input [511:0] block_i,
    output reg    ready_o,
    output reg    done_o,
    output [255:0] digest_o
);

    // -------------------------------------------------------------------------
    // NIST Initial Hash Values
    // -------------------------------------------------------------------------
    localparam [31:0]
        IV0=32'h6a09e667, IV1=32'hbb67ae85,
        IV2=32'h3c6ef372, IV3=32'ha54ff53a,
        IV4=32'h510e527f, IV5=32'h9b05688c,
        IV6=32'h1f83d9ab, IV7=32'h5be0cd19;

    // -------------------------------------------------------------------------
    // Round constants
    // -------------------------------------------------------------------------
    reg [31:0] K [0:63];
    initial begin
        K[ 0]=32'h428a2f98; K[ 1]=32'h71374491; K[ 2]=32'hb5c0fbcf; K[ 3]=32'he9b5dba5;
        K[ 4]=32'h3956c25b; K[ 5]=32'h59f111f1; K[ 6]=32'h923f82a4; K[ 7]=32'hab1c5ed5;
        K[ 8]=32'hd807aa98; K[ 9]=32'h12835b01; K[10]=32'h243185be; K[11]=32'h550c7dc3;
        K[12]=32'h72be5d74; K[13]=32'h80deb1fe; K[14]=32'h9bdc06a7; K[15]=32'hc19bf174;
        K[16]=32'he49b69c1; K[17]=32'hefbe4786; K[18]=32'h0fc19dc6; K[19]=32'h240ca1cc;
        K[20]=32'h2de92c6f; K[21]=32'h4a7484aa; K[22]=32'h5cb0a9dc; K[23]=32'h76f988da;
        K[24]=32'h983e5152; K[25]=32'ha831c66d; K[26]=32'hb00327c8; K[27]=32'hbf597fc7;
        K[28]=32'hc6e00bf3; K[29]=32'hd5a79147; K[30]=32'h06ca6351; K[31]=32'h14292967;
        K[32]=32'h27b70a85; K[33]=32'h2e1b2138; K[34]=32'h4d2c6dfc; K[35]=32'h53380d13;
        K[36]=32'h650a7354; K[37]=32'h766a0abb; K[38]=32'h81c2c92e; K[39]=32'h92722c85;
        K[40]=32'ha2bfe8a1; K[41]=32'ha81a664b; K[42]=32'hc24b8b70; K[43]=32'hc76c51a3;
        K[44]=32'hd192e819; K[45]=32'hd6990624; K[46]=32'hf40e3585; K[47]=32'h106aa070;
        K[48]=32'h19a4c116; K[49]=32'h1e376c08; K[50]=32'h2748774c; K[51]=32'h34b0bcb5;
        K[52]=32'h391c0cb3; K[53]=32'h4ed8aa4a; K[54]=32'h5b9cca4f; K[55]=32'h682e6ff3;
        K[56]=32'h748f82ee; K[57]=32'h78a5636f; K[58]=32'h84c87814; K[59]=32'h8cc70208;
        K[60]=32'h90befffa; K[61]=32'ha4506ceb; K[62]=32'hbef9a3f7; K[63]=32'hc67178f2;
    end

    // -------------------------------------------------------------------------
    // Hash state registers H0-H7
    // -------------------------------------------------------------------------
    reg [31:0] H0,H1,H2,H3,H4,H5,H6,H7;

    // -------------------------------------------------------------------------
    // Working variables a-h (Fig. 7 left registers)
    // -------------------------------------------------------------------------
    reg [31:0] a,b,c,d,e,f,g,h_r;   // h_r to avoid keyword clash

    // -------------------------------------------------------------------------
    // Round counter
    // -------------------------------------------------------------------------
    reg [5:0] round_cnt;

    // -------------------------------------------------------------------------
    // FSM state encoding
    // -------------------------------------------------------------------------
    localparam [2:0] ST_IDLE=3'd0, ST_LOAD=3'd1,
                     ST_ROUND=3'd2, ST_ACCUM=3'd3, ST_DONE=3'd4;
    reg [2:0] state;

    // -------------------------------------------------------------------------
    // Combinational schedule control (WIRES, not regs)
    // This is the key timing fix: schedule sees load/advance in the SAME cycle.
    // -------------------------------------------------------------------------
    wire sched_load    = (state == ST_LOAD);
    wire sched_advance = (state == ST_ROUND);

    // -------------------------------------------------------------------------
    // Message schedule instantiation
    // -------------------------------------------------------------------------
    wire [31:0] Wt;
    sha256_schedule u_sched (
        .clk      (clk),
        .rst_n    (rst_n),
        .load_i   (sched_load),
        .block_i  (block_i),
        .advance_i(sched_advance),
        .Wt_o     (Wt)
    );

    // -------------------------------------------------------------------------
    // Round function instantiation (fully combinational, Fig. 7 center)
    // -------------------------------------------------------------------------
    wire [31:0] a_new,b_new,c_new,d_new,e_new,f_new,g_new,h_new;
    sha256_round u_round (
        .a(a),.b(b),.c(c),.d(d),
        .e(e),.f(f),.g(g),.h(h_r),
        .Wt(Wt), .Kt(K[round_cnt]),
        .a_new(a_new),.b_new(b_new),.c_new(c_new),.d_new(d_new),
        .e_new(e_new),.f_new(f_new),.g_new(g_new),.h_new(h_new)
    );

    // -------------------------------------------------------------------------
    // Digest output: H0||H1||...||H7
    // -------------------------------------------------------------------------
    assign digest_o = {H0,H1,H2,H3,H4,H5,H6,H7};

    // -------------------------------------------------------------------------
    // FSM — clocked
    // -------------------------------------------------------------------------
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state     <= ST_IDLE;
            ready_o   <= 1'b1;
            done_o    <= 1'b0;
            round_cnt <= 6'd0;
            H0<=IV0; H1<=IV1; H2<=IV2; H3<=IV3;
            H4<=IV4; H5<=IV5; H6<=IV6; H7<=IV7;
            a<=0; b<=0; c<=0; d<=0;
            e<=0; f<=0; g<=0; h_r<=0;
        end
        else begin
            done_o <= 1'b0;   // default

            if (init_i) begin
                // Re-initialise between messages (without full reset)
                H0<=IV0; H1<=IV1; H2<=IV2; H3<=IV3;
                H4<=IV4; H5<=IV5; H6<=IV6; H7<=IV7;
                state   <= ST_IDLE;
                ready_o <= 1'b1;
            end
            else case (state)

                // ----------------------------------------------------------
                ST_IDLE: begin
                    ready_o <= 1'b1;
                    if (block_valid_i) begin
                        ready_o <= 1'b0;
                        state   <= ST_LOAD;
                    end
                end

                // ----------------------------------------------------------
                // ST_LOAD:
                //   sched_load wire = 1 THIS CYCLE.
                //   At THIS posedge, schedule latches W[0..15] from block_i.
                //   After this posedge: Wt_o = W[0].
                //   We also latch a-h = H0-H7 and set round_cnt = 0.
                //   Next state = ST_ROUND.
                // ----------------------------------------------------------
                ST_LOAD: begin
                    a<=H0; b<=H1; c<=H2; d<=H3;
                    e<=H4; f<=H5; g<=H6; h_r<=H7;
                    round_cnt <= 6'd0;
                    state     <= ST_ROUND;
                end

                // ----------------------------------------------------------
                // ST_ROUND:
                //   sched_advance wire = 1 THIS CYCLE.
                //   sha256_round (combinational) computes using:
                //     Wt = buf[0] = W[round_cnt]   ← correct
                //     Kt = K[round_cnt]             ← correct
                //     a..h = previous round outputs
                //   At THIS posedge:
                //     a-h registers capture a_new..h_new
                //     round_cnt increments
                //     schedule shifts (buf[0]<-buf[1], buf[15]<-W_new)
                //     After posedge: Wt_o = W[round_cnt+1]  ← ready for next
                // ----------------------------------------------------------
                ST_ROUND: begin
                    a<=a_new; b<=b_new; c<=c_new; d<=d_new;
                    e<=e_new; f<=f_new; g<=g_new; h_r<=h_new;
                    round_cnt <= round_cnt + 1;
                    if (round_cnt == 6'd63)
                        state <= ST_ACCUM;
                end

                // ----------------------------------------------------------
                // ST_ACCUM: H' = H + [a..h]  (right-side adders, Fig. 7)
                // ----------------------------------------------------------
                ST_ACCUM: begin
                    H0<=H0+a; H1<=H1+b; H2<=H2+c; H3<=H3+d;
                    H4<=H4+e; H5<=H5+f; H6<=H6+g; H7<=H7+h_r;
                    state <= ST_DONE;
                end

                // ----------------------------------------------------------
                ST_DONE: begin
                    done_o  <= 1'b1;
                    ready_o <= 1'b1;
                    state   <= ST_IDLE;
                end

                default: state <= ST_IDLE;
            endcase
        end
    end

endmodule
